  int      arm_start = 100;           // 随机初值档：复位后这么多拍才开始"等首次相等"
  logic [63:0] addr_pool [4];         // 地址小池（初始时随机取 4 个、低 3 位清零）
  always #5 clk = ~clk;
  assign clock = clk;

