  // END GENERATED

  // ---- 手写约束：随机值之上修正几处"真实环境里不会出现、会让 golden 自己卡死"的组合 ----
  //   (1) load 回写的 robIdx 按程序序唯一递增（RobSize=160 绕圈、flag 翻转）：LoadQueueUncache 里
  //       两条同 robIdx 的 MMIO 会同时"成为 ROB 头"、一起进 S_RESP 而只有一条真发出，另一条永远等回应；
  //   (2) mmio 与 nc 互斥（同置的条目走 MMIO 路由却不等 ROB 头，同上死锁）；
  //   (3) ROB 的 pendingPtr 取最近分配的 robIdx 往回 0..7 条之一，让"MMIO 条目成了 ROB 头"常发生；
  //   (4) redirect 指向最近 24 条以内的某条（随机 robIdx 几乎总比在册条目老，每次 redirect 都会冲光整个队列）。
  //   这些只是让激励走得更深；比较本身不依赖它们（两侧同初值下对任意输入都应逐拍相同）。
  int unsigned rob_seq = 0;
  function automatic void rob_of(input int unsigned s, output logic f, output logic [7:0] v);
    f = (s / 160) % 2;
    v = s % 160;
  endfunction
  task automatic constrain_inputs();
    int unsigned back;
    if (io_ldu_ldin_0_valid) begin rob_seq++; rob_of(rob_seq, io_ldu_ldin_0_bits_uop_robIdx_flag, io_ldu_ldin_0_bits_uop_robIdx_value); end
    if (io_ldu_ldin_1_valid) begin rob_seq++; rob_of(rob_seq, io_ldu_ldin_1_bits_uop_robIdx_flag, io_ldu_ldin_1_bits_uop_robIdx_value); end
    if (io_ldu_ldin_2_valid) begin rob_seq++; rob_of(rob_seq, io_ldu_ldin_2_bits_uop_robIdx_flag, io_ldu_ldin_2_bits_uop_robIdx_value); end
    if (io_ldu_ldin_0_bits_mmio) io_ldu_ldin_0_bits_nc = 0;
    if (io_ldu_ldin_1_bits_mmio) io_ldu_ldin_1_bits_nc = 0;
    if (io_ldu_ldin_2_bits_mmio) io_ldu_ldin_2_bits_nc = 0;
    back = $urandom_range(24);
    rob_of((rob_seq > back) ? rob_seq - back : 0, io_brqRedirect_bits_robIdx_flag, io_brqRedirect_bits_robIdx_value);
    back = $urandom_range(7);
    rob_of((rob_seq > back) ? rob_seq - back : 0, io_rob_pendingPtr_flag, io_rob_pendingPtr_value);
  endtask

  initial begin
    string ir;
    int seed;
    void'($value$plusargs("ncycles=%d", NCYCLES));
    if (!$value$plusargs("ntb_random_seed=%d", seed)) seed = 0;
    if ($value$plusargs("vcs+initreg+%s", ir)
        && (ir == "0" || ir == "1" || (ir == "random" && seed == 1))) cmp_all = 1;
    $display("UT LsqWrapper: ncycles=%0d initreg=%s seed=%0d cmp_all=%0d", NCYCLES, ir, seed, cmp_all);
    foreach (addr_pool[k]) addr_pool[k] = {$urandom(), $urandom()} & ~64'h7;
    reset = 1;
    drive_inputs();
    for (cyc = 0; cyc < NCYCLES; cyc++) begin
      @(negedge clk);
      if (cyc % 10000 < 3) reset = 1; else reset = 0;
      if ((cyc / 4000) % 2 == 0) begin p_valid = 30; p_ready = 85; end
      else                       begin p_valid = 10; p_ready = 15; end
      drive_inputs();
      constrain_inputs();
      #2;
      compare_outputs();
    end
    void'(report_toggle());
    $display("checks=%0d errors=%0d", checks, errors);
    if (errors == 0) $display("TEST PASSED"); else $display("TEST FAILED");
    $finish;
  end
